import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>
#include <cstdint>

__global__ void tanh_kernel_vec(
    const float* __restrict__ input,
    float* __restrict__ output,
    int64_t numel
) {
    const int64_t thread_index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int64_t stride = static_cast<int64_t>(blockDim.x) * gridDim.x;
    const int64_t vec_numel = numel / 4;
    const float4* __restrict__ input4 = reinterpret_cast<const float4*>(input);
    float4* __restrict__ output4 = reinterpret_cast<float4*>(output);
    for (int64_t index = thread_index; index < vec_numel; index += stride) {
        const float4 value = input4[index];
        output4[index] = make_float4(
            __tanhf(value.x),
            __tanhf(value.y),
            __tanhf(value.z),
            __tanhf(value.w)
        );
    }
    const int64_t tail_start = vec_numel * 4;
    for (int64_t index = tail_start + thread_index; index < numel; index += stride) {
        output[index] = __tanhf(input[index]);
    }
}
__global__ void tanh_kernel_scalar(
    const float* __restrict__ input,
    float* __restrict__ output,
    int64_t numel
) {
    const int64_t thread_index = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int64_t stride = static_cast<int64_t>(blockDim.x) * gridDim.x;
    for (int64_t index = thread_index; index < numel; index += stride) {
        output[index] = __tanhf(input[index]);
    }
}
torch::Tensor tanh_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must have dtype torch.float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    auto output = torch::empty_like(input);
    const int64_t numel = input.numel();
    if (numel == 0) {
        return output;
    }
    c10::cuda::CUDAGuard device_guard(input.device());
    constexpr int threads = 128;
    const uintptr_t input_addr = reinterpret_cast<uintptr_t>(input.data_ptr<float>());
    const uintptr_t output_addr = reinterpret_cast<uintptr_t>(output.data_ptr<float>());
    const bool aligned = ((input_addr | output_addr) & (alignof(float4) - 1)) == 0;
    const int64_t work_items = aligned ? ((numel + 3) / 4) : numel;
    const int64_t required_blocks = (work_items + threads - 1) / threads;
    const int blocks = static_cast<int>(required_blocks < 4096 ? required_blocks : 4096);
    auto stream = at::cuda::getCurrentCUDAStream(input.device().index());
    if (aligned) {
        tanh_kernel_vec<<<blocks, threads, 0, stream.stream()>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            numel
        );
    } else {
        tanh_kernel_scalar<<<blocks, threads, 0, stream.stream()>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            numel
        );
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""

_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor tanh_cuda(torch::Tensor input);
"""

_tanh_extension = load_inline(
    name="custom_tanh_cuda",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["tanh_cuda"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _tanh_extension.tanh_cuda(x)

